// Normalize RSS item to Laravel ingest format
const items = [];
for (const item of items_all) {
  const sourceMap = {
    'bbc-rss': 'BBC World',
    'reuters-rss': 'Reuters Tech',
    'arstechnica-rss': 'Ars Technica',
    'nyt-tech-rss': 'NYT Tech'
  };
  const sourceKey = item._meta?.source || 'unknown';
  const source = sourceMap[sourceKey] || sourceKey;

  // Determine category from title/summary
  let category = 'general';
  const text = ((item.title || '') + ' ' + (item.summary || '')).toLowerCase();
  if (text.includes('ai') || text.includes('artificial intelligence') || text.includes('chatgpt') || text.includes('machine learning')) category = 'technology';
  else if (text.includes('sport') || text.includes('football') || text.includes('basketball') || text.includes('tennis')) category = 'sports';
  else if (text.includes('politics') || text.includes('election') || text.includes('government')) category = 'politics';
  else if (text.includes('business') || text.includes('economy') || text.includes('market')) category = 'business';
  else if (text.includes('science') || text.includes('research')) category = 'science';
  else if (text.includes('health') || text.includes('medical') || text.includes('virus')) category = 'health';

  items.push({
    title: item.title || 'Untitled',
    url: item.url || item.link || '',
    source: source,
    published_at: item.pubDate || item.datePublished || new Date().toISOString(),
    summary: (item.summary || item.description || '').replace(/<[^>]*>/g, '').substring(0, 500),
    category: category
  });
}
return items;

const sourceMap = { 'bbc-rss': 'BBC World', 'reuters-rss': 'Reuters Tech', 'arstechnica-rss': 'Ars Technica', 'nyt-tech-rss': 'NYT Tech' };
