  else if (text.includes('health') || text.includes('medical')) category = 'health';
  items.push({ json: { title: item.json.title || 'Untitled', url: item.json.url || item.json.link || '', source, published_at: item.json.pubDate || new Date().toISOString(), summary: (item.json.summary || item.json.description || '').replace(/<[^>]*>/g, '').substring(0, 500), category } });
